from collections import defaultdict
docs = {1: "red shoes", 2: "blue shoes", 3: "red wool socks", 4: "blue hat"}

index = defaultdict(set)
for doc_id, text in docs.items():
    for word in text.lower().split():
        index[word].add(doc_id)

def search(query):
    lists = [index.get(word, set()) for word in query.lower().split()]
    return sorted(set.intersection(*lists)) if lists else []

print({word: sorted(ids) for word, ids in sorted(index.items())})
print(search("red shoes"), search("Blue"), search("green"))
